const parseSemver = (version) => {
  const defaultSemverInfo = {
    full: "",
    major: 0,
    minor: 0,
    patch: 0,
    prerelease: "",
    build: "",
    // sing-box
    alphaVersion: 0,
  };
  if (!version) return defaultSemverInfo;

  const semverRegex =
    /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

  const match = version.match(semverRegex);

  if (match) {
    const [full, major, minor, patch, prerelease, build] = match;
    if (prerelease) {
      defaultSemverInfo.alphaVersion = Number(prerelease.split(".")[1]);
    }
    defaultSemverInfo.full = full;
    defaultSemverInfo.major = Number(major);
    defaultSemverInfo.minor = Number(minor);
    defaultSemverInfo.patch = Number(patch);
    defaultSemverInfo.prerelease = prerelease;
    defaultSemverInfo.build = build;
    return defaultSemverInfo;
  } else {
    throw new Error("Parse Semver failed");
  }
};

const uaLookup = (ua = "") => {
  if (ua === "") {
    return undefined;
  }

  const defaultUaInfo = {
    SFM: false,
    SFI: false,
    SFT: false,
    SFA: false,
    version: parseSemver(undefined),
    language: "",
  };

  const regex =
    /^([^/]+)\/(\S+) \((?:Build )?([^;]+); sing-box ([^;]+); language ([^)]+)\)$/;

  const uaMatched = ua.match(regex);
  if (!uaMatched || uaMatched.length < 6) {
    return defaultUaInfo;
  }

  defaultUaInfo.SFM = uaMatched[1] === "SFM";
  defaultUaInfo.SFI = uaMatched[1] === "SFI";
  defaultUaInfo.SFT = uaMatched[1] === "SFT";
  defaultUaInfo.SFA = uaMatched[1] === "SFA";

  defaultUaInfo.version = parseSemver(uaMatched[2]);

  // 语言处理
  if (defaultUaInfo.SFM || defaultUaInfo.SFI || defaultUaInfo.SFT) {
    defaultUaInfo.language = uaMatched[5].startsWith("zh-Hans")
      ? "zh_CN"
      : "en_US";
  } else if (defaultUaInfo.SFA) {
    defaultUaInfo.language = uaMatched[5];
  }

  return defaultUaInfo;
};

const generateContext = async () => {
  const lookupQuery = (name) => {
    return $options?._req?.query?.[name];
  };

  const generated = {
    config: JSON.parse($files[0]),
    experimental: {},
    ua: uaLookup(
      $options?._req?.headers?.["user-agent"] ||
        $options?._req?.headers?.["User-Agent"] ||
        context.test?.ua,
    ),
  };

  if (lookupQuery("user") || context.test?.user) {
    const userID = lookupQuery("user") || context.test?.user || "";
    const produced = await produceArtifact({
      type: lookupQuery("prod_type") || "collection",
      name: userID,
      platform: "json",
      produceType: "internal",
    });
    generated.proxies = produced.filter((proxy) =>
      [
        "socks",
        "http",
        "ss",
        "vmess",
        "trojan",
        "naive",
        "hysteria",
        "hysteria2",
        "vless",
        "tuic",
        "anytls",
        "tor",
        "ssh",
        "snell",
      ].includes(proxy.type),
    );
    generated.endpoints = produced.filter((proxy) =>
      ["wireguard", "tailscale"].includes(proxy.type),
    );
  } else {
    generated.proxies = [];
  }

  (lookupQuery("experimental") || context.test?.experimental || "")
    .split(",")
    .map((fe) => {
      generated.experimental[fe] = true;
    });

  return generated;
};

const applySortAndCompability = ({ proxies = [], ...rest }) => {
  const sortedProxies = context.features.location.sortProxies({ proxies });

  // Notice heer , different platform has different name selector (tag or name)
  const names = produce(proxies).map((pp) => pp.tag);
  return {
    proxies: sortedProxies.filter((sp) => names.includes(sp.name)),
    ...rest,
  };
};

const applyTransport = ({
  proxies = [],
  config = {},
  experimental = {},
  ua = {},
  ...rest
}) => {
  const transportGroups = context.features.transport.completeTransport({
    proxies: proxies,
    detourName: (cca2) => {
      let defaultTransportName = "🚀 Transport";
      const trnaslation = {
        zh_CN: "🚀 链式传输",
        en_US: defaultTransportName,
      };
      if (ua && ua.language in trnaslation) {
        defaultTransportName = trnaslation[ua.language];
      }
      if (!cca2) {
        return defaultTransportName;
      }
      return defaultTransportName + " (" + cca2 + ")";
    },
  });

  Object.keys(transportGroups).map((selectorName) => {
    const selected = transportGroups[selectorName];
    if (selected.use && selected.proxies.length > 1) {
      const transportGroup = {
        type: "selector",
        tag: selected.name,
        outbounds: [...selected.proxies],
      };
      config.outbounds = [transportGroup, ...config.outbounds];
    }
  });

  return {
    proxies: proxies.filter(
      (proxy) =>
        !context.features.transport.isDestionation({ proxy }) ||
        "dialer-proxy" in proxy,
    ),
    experimental,
    config,
    ua,
    ...rest,
  };
};

const applyGeoSiteGeoIP = ({ proxies = [], config = {}, ...rest }) => {
  const directIP = new Set();
  const directSite = new Set();
  for (const proxy of proxies) {
    if (proxy.server === undefined || proxy["dialer-proxy"]) {
      continue;
    }
    const serverAddr = proxy.server;
    if (serverAddr.includes(":")) {
      // IPv6
      directIP.add(serverAddr);
      continue;
    }

    const dots = serverAddr.split(".");
    if (dots.length === 4 && Number.isInteger(Number(dots[3])))
      directIP.add(serverAddr); // IPv4
    else directSite.add(serverAddr); // Domain
  }
  if (context.secret?.metadata?.ghproxy)
    directSite.add(context.secret?.metadata?.ghproxy);
  if (context.secret?.metadata?.subscribeURL)
    directSite.add(context.secret?.metadata?.subscribeURL);

  config.route?.rule_set?.map((rs) => {
    if (rs.tag === "@geosite-direct" && directSite.size > 0) {
      rs.rules[0].domain = [...(rs.rules[0].domain ?? []), ...[...directSite]];
    }

    if (rs.tag === "@geoip-direct" && directIP.size > 0) {
      rs.rules[0].ip_cidr = [
        ...(rs.rules[0].ip_cidr ?? []),
        ...[...directIP].map((ip) =>
          ip.includes(":") ? ip + "/128" : ip + "/32",
        ),
      ];
    }
  });

  return { proxies, config, ...rest };
};

const applyPushGroup = ({ proxies = [], config = {}, ...rest }) => {
  const out = proxies.filter(
    (proxy) =>
      proxy?.properties?.hidden === undefined || !proxy.properties.hidden,
  );
  config.outbounds
    .filter((p) => ["selector", "urltest"].includes(p.type))
    .map((selector) => {
      if (
        [
          "🙋 Select",
          "🔍 Google",
          "🐈 Git",
          "🪟 Microsoft",
          "📺 Entertainment",
          "🤖 AI-Service",
          "🍎 Apple",
        ].includes(selector.tag)
      ) {
        selector.outbounds.push(...out.map((o) => o.name));
      } else if (["✈️ TelegramDC1(NA)"].includes(selector.tag)) {
        selector.outbounds.push(
          ...out
            .filter(
              (o) =>
                context.features.location.getArea(o) === "AREA_NORTH_AMERICA" ||
                context.features.location.getLocation(o) === "JP",
            )
            .map((o) => o.name),
        );
      } else if (["✈️ TelegramDC4(EU)"].includes(selector.tag)) {
        selector.outbounds.push(
          ...out
            .filter(
              (o) =>
                context.features.location.getArea(o) === "AREA_EUROPE" ||
                context.features.location.getLocation(o) === "HK",
            )
            .map((o) => o.name),
        );
      } else if (["✈️ TelegramDC5(AP)"].includes(selector.tag)) {
        selector.outbounds.push(
          ...out
            .filter((o) => context.features.location.getArea(o) === "AREA_ASIA")
            .map((o) => o.name),
        );
      }
    });
  return { proxies, config, ...rest };
};

const applyInternalDNSResolver = ({ config = {}, proxies = [], ...rest }) => {
  const isDomain = (addr) => {
    if (!addr || addr.includes(":")) return false; // empty or IPv6
    const dots = addr.split(".");
    // not an IPv4 literal => treat as domain
    return !(dots.length === 4 && Number.isInteger(Number(dots[3])));
  };

  // normalize proxy.properties.dns (string shorthand or object) into a
  // sing-box dns server object with a deterministic, dedupe-friendly tag.
  const buildSingDns = (proxy) => {
    const dns = proxy.properties.dns;
    const props = { type: "", server: "", path: "", port: 0 };
    if (typeof dns === "string") {
      props.type = "udp";
      props.server = dns;
    } else {
      props.type = dns.type ?? "";
      props.server = dns.server ?? "";
      props.path = dns.path ?? "";
      props.port = dns.port ?? 0;
    }

    const tag =
      "dns-" +
      [props.type, props.server, props.path, props.port]
        .filter((v) => v)
        .join("_");

    const singDns = { type: props.type, server: props.server, tag };
    if (props.port) singDns.server_port = props.port;
    if ((props.type === "https" || props.type === "h3") && props.path !== "") {
      singDns.path = props.path;
    }

    // a dns server addressed by a domain needs a bootstrap resolver to
    // look up that address itself.
    if (isDomain(singDns.server)) {
      singDns.domain_resolver = { server: context.const.dns.bootstrapDNSTag };
    }

    singDns.detour = context.const.outbound.direct;
    return singDns;
  };

  // some airports ship their own dns. expose each as a sing-box dns server and
  // point the proxy's outbound.domain_resolver at it (sub-store passes
  // `_domain_resolver` through). the matching route-level dns.rules are added
  // later in post from the produced outbounds (see apply-internal-dns-rules).
  const dnsServers = {};

  for (const proxy of proxies) {
    if (!proxy.properties?.dns) continue;

    const singDns = buildSingDns(proxy);
    dnsServers[singDns.tag] = singDns;
    proxy._domain_resolver = { server: singDns.tag };
  }

  if (Object.keys(dnsServers).length === 0) {
    return { config, proxies, ...rest };
  }

  config.dns = config.dns ?? {};
  config.dns.servers = [
    ...(config.dns.servers ?? []),
    ...Object.values(dnsServers),
  ];

  return { config, proxies, ...rest };
};

const applyEndpoints = ({ config = {}, endpoints = [], ...rest }) => {
  const tailnetIPRanges = ["100.64.0.0/10", "fd7a:115c:a1e0::/48"];

  const endpoint = $options?._req?.query?.endpoint ?? "";
  const allowRouteAll =
    $options?._req?.query?.allow_route_all === "true" ?? false;

  // endpoint id generated by:
  // $ openssl rand -hex 16
  const endpointIDs = endpoint.split("_");
  const availableEndpoints = (endpoints ?? [])
    .filter((ep) =>
      (endpointIDs ?? []).some(
        (eid) =>
          (ep.type === "tailscale" || ep.type === "wireguard") &&
          ep.properties?.endpoint?.id == eid,
      ),
    )
    .map((ep) => {
      ep.detour = ep.detour ?? context.const.outbound.direct;
      return ep;
    });

  if (availableEndpoints.length == 0) {
    // no endpoint available , so exclude tailnet ip range to tun configure.
    (config.inbounds ?? [])
      .filter((inbound) => inbound.type === "tun")
      .map(
        (tunin) =>
          (tunin.route_exclude_address = [
            ...(tunin.route_exclude_address ?? []),
            ...tailnetIPRanges,
          ]),
      );
    return { config, ...rest };
  } else if (allowRouteAll)
    // use `allow_route_all` to fix that some ip range may not routed
    // due the ip range was excluded by tun config.
    (config.inbounds ?? [])
      .filter((inbound) => inbound.type === "tun")
      .map((tunin) => (tunin.route_exclude_address = []));

  availableEndpoints.map((ep) => {
    if (ep.type === "wireguard") {
      config.route = {
        ...(config.route ?? {}),
        rules: [
          {
            action: "route",
            ip_cidr: ep.properties?.endpoint?.route?.ip_cidr ?? ep.address,
            outbound: ep.name,
          },
          ...(config.route?.rules ?? []),
        ],
      };
      return;
    }
    // tailscale
    config.dns = {
      ...(config.dns ?? {}),
      servers: [
        ...(config.dns?.servers ?? []),
        {
          type: "tailscale",
          tag: "dns-" + ep.name,
          endpoint: ep.name,
          accept_search_domain: true,
        },
      ],
      rules: [
        {
          action: "evaluate",
          server: "dns-" + ep.name,
        },
        {
          match_response: true,
          ip_accept_any: true,
          action: "respond",
        },
        ...(config.dns?.rules ?? []),
      ],
    };
    config.route = {
      ...(config.route ?? {}),
      rules: [
        {
          action: "route",
          ip_cidr: ep.properties?.endpoint?.route?.ip_cidr ?? tailnetIPRanges,
          outbound: ep.name,
        },
        {
          action: "route",
          domain_suffix:
            ep.properties?.endpoint?.route?.domain_suffix ?? "ts.net",
          outbound: ep.name,
        },
        ...(config.route?.rules ?? []),
      ],
    };
    return;
  });

  return { config, endpoints: availableEndpoints, ...rest };
};

const assembleConfig = ({
  config = {},
  proxies = [],
  endpoints = [],
  ...rest
}) => {
  return {
    ...rest,
    config: {
      ...config,
      outbounds: [...(config.outbounds ?? []), ...produce(proxies)],
      endpoints: [...(config.endpoints ?? []), ...produceEndpoint(endpoints)],
    },
  };
};

const applySyncDomainResolver = ({ config = {}, ...rest }) => {
  const isDomain = (addr) => {
    if (!addr || addr.includes(":")) return false; // empty or IPv6
    const dots = addr.split(".");
    // not an IPv4 literal => treat as domain
    return !(dots.length === 4 && Number.isInteger(Number(dots[3])));
  };

  const resolverTag = (dr) => (typeof dr === "string" ? dr : dr?.server);

  // walk the produced outbounds: any node whose server is a domain and that
  // carries a domain_resolver (set in pre via _domain_resolver) gets a
  // route-level dns.rule, so external resolution of that domain matches the
  // internal outbound resolution instead of diverging.
  const servedDomains = {};
  for (const outbound of config.outbounds ?? []) {
    if (!isDomain(outbound.server)) continue;

    let tag = resolverTag(outbound.domain_resolver);
    if (!tag) {
      const routeDefaultResolver = config?.route?.default_domain_resolver;
      if (routeDefaultResolver && typeof routeDefaultResolver === "string") {
        tag = routeDefaultResolver;
      } else if (
        routeDefaultResolver.server &&
        typeof routeDefaultResolver.server === "string"
      ) {
        tag = routeDefaultResolver.server;
      } else {
        tag = context.const.dns.bootstrapDNSTag;
      }
    }

    servedDomains[tag] = servedDomains[tag] ?? new Set();
    servedDomains[tag].add(outbound.server);
  }

  config.dns = {
    ...(config.dns ?? {}),
    rules: [
      ...(Object.entries(servedDomains).map(([server, domains]) => ({
        domain: [...domains],
        action: "route",
        server,
      })) ?? []),
      ...(config.dns.rules ?? []),
    ],
  };

  return { config, ...rest };
};

const applyBoostrapDirect = ({ config = {}, ...rest }) => {
  const ghproxy = context.secret?.metadata?.ghproxy ?? "hk.gh-proxy.org";
  const githubDomains = [
    "raw.githubusercontent.com",
    "github.com",
    "gist.githubusercontent.com",
  ];

  if (Array.isArray(config.route?.rule_set)) {
    config.route.rule_set.map((ruleset) => {
      if (
        ruleset.type === "remote" &&
        githubDomains.some((domain) =>
          ruleset.url.startsWith("https://" + domain),
        )
      ) {
        ruleset.url = `https://${ghproxy}/${ruleset.url}`;
        ruleset.http_client = context.const.ruleset.bootstrapHTTPClient;
      }
    });
  }
  if (
    config.experimental?.clash_api?.external_ui_download_url &&
    githubDomains.some((domain) =>
      config.experimental.clash_api.external_ui_download_url.startsWith(
        "https://" + domain,
      ),
    )
  ) {
    config.experimental.clash_api.external_ui_download_url = `https://${ghproxy}/${config.experimental.clash_api.external_ui_download_url}`;
    config.experimental.clash_api.external_ui_download_detour =
      context.const.outbound.directBootstrap;
  }

  return { config, ...rest };
};

const applyDnsEnhanced = ({ config = {}, experimental = {}, ...rest }) => {
  // client subnet
  const getClientIP = () => {
    const req = $options?._req;
    const headers = req?.headers ?? {};

    const ip =
      headers["cf-connecting-ip"] ||
      headers["true-client-ip"] ||
      headers["x-real-ip"] ||
      headers["x-forwarded-for"]?.split(",")[0]?.trim() ||
      req?.socket?.remoteAddress;
    return ip === undefined ? "" : ip.trim();
  };

  let ip = getClientIP();
  if (ip === "") ip = "114.114.114.114";
  for (const dnsRule of [...(config?.dns?.rules ?? [])]) {
    if (
      dnsRule.client_subnet === "0.0.0.0/0" ||
      dnsRule.client_subnet === "::/0"
    ) {
      dnsRule.client_subnet = ip + (ip.includes(":") ? "/128" : "/32");
    }
  }

  // experimental h3
  if (experimental.dns_cn_use_h3 && Array.isArray(config?.dns?.servers))
    config.dns.servers.map((dns) => {
      if (dns.tag === "dns-cn" && dns.type === "https") dns.type = "h3";
    });

  // leak
  if (experimental.dns_leak_boost && Array.isArray(config?.dns?.rules)) {
    config.dns.rules.map((r) => {
      if (r.server === "dns-ecs") {
        r.server = "dns-cn";
        r.client_subnet = undefined;
      }
    });
  }

  // no local
  if (experimental.dns_local_use_dhcp && Array.isArray(config?.dns?.servers))
    config.dns.servers
      .filter((server) => server.type === "local")
      .forEach((server) => (server.type = "dhcp"));
  
  return { config, experimental, ...rest };
};

const applyPlatformSettings = ({ config = {}, ua = undefined, ...rest }) => {
  const ret = { config, ua, ...rest };
  if (ua === undefined) {
    return ret;
  }
  config?.inbounds
    ?.filter((inb) => inb.type === "tun")
    .map((tunInbound) => {
      if (ua.SFM) {
        // on macos , only set ipv6 dns address to fix the program
        // which read the /etc/resolv.conf as major dns resolver config.
        if (tunInbound.dns_address)
          tunInbound.dns_address = tunInbound.dns_address.filter((addr) =>
            addr.includes(":"),
          );
        // on macos , gvisor has better performance.
        tunInbound.stack = "gvisor";
      }
    });

  return ret;
};

const applySuperSecretSettingsFunc = () => {
  if (context.secret?.superSecretSettings) {
    return context.secret?.superSecretSettings;
  }

  return ({...rest}) => ({ ...rest });
};

const applyTranslation = ({ config = {}, ua = undefined, ...rest }) => {
  const ret = { config, ua, ...rest };

  const globalTranslation = {
    zh_CN: {
      "🌐 Direct": "🌐 直连",
      "🙋 Select": "🙋 手动选择",
      "🔍 Google": "🔍 谷歌服务",
      "🐈 Git": "🐈 开发服务",
      "🪟 Microsoft": "🪟 微软服务",
      "📺 Entertainment": "📺 流媒体",
      "🤖 AI-Service": "🤖 AI服务",
      "🍎 Apple": "🍎 苹果服务",

      "✈️ TelegramDC1(NA)": "✈️ 电报DC1 (北美)",
      "✈️ TelegramDC4(EU)": "✈️ 电报DC4 (欧洲)",
      "✈️ TelegramDC5(AP)": "✈️ 电报DC5 (亚太)",
    },
  };

  if (!config || !ua || !(ua.language in globalTranslation)) {
    return ret;
  }

  let jsonConfig = JSON.stringify(config);
  Object.keys(globalTranslation[ua.language]).map((raw) => {
    const target = globalTranslation[ua.language][raw];
    jsonConfig = jsonConfig.replaceAll(raw, target);
  });

  return { config: JSON.parse(jsonConfig), ua, ...rest };
};

const emitContent = ({ config = {} }) => {
  $content = JSON.stringify(config, null, 2);
  return { config };
};

await generateContext()
  .then(applySortAndCompability)
  .then(applyTransport)
  .then(applyGeoSiteGeoIP)
  .then(applyPushGroup)
  .then(applyInternalDNSResolver)
  .then(applyEndpoints)
  .then(assembleConfig)
  .then(applySyncDomainResolver)
  .then(applyBoostrapDirect)
  .then(applyDnsEnhanced)
  .then(applyPlatformSettings)
  .then(applySuperSecretSettingsFunc())
  .then(applyTranslation)
  .then(emitContent);
